#    - export PRIVATE_KEY=0x…              （合約現任 owner，見下）
#    - export BASE_SEPOLIA_RPC_URL=…
#    - export BASESCAN_API_KEY=…           （選用，開 --verify）
#    - export ADMIN_ADDRESS / KEEPER_ADDRESS / GUARDIAN_ADDRESS = 三把不同的 key
#      （沒設會退回部署者 —— GuardedOracle 的偏離上限 / freeze / pause 等於零）
