# ── helpers (this wizard's own, beyond the library) ──────────────────────

die()  { printf '\n  %s✖ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
run()  { printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"; "$@"; }

remember() { printf 'export %s=%s\n' "$1" "$2" >> "$SCRATCH"; ok "記下 $1=$2"; }

# grab the last 0x-address on any line containing $1, from log file $2
grab_addr() { grep -E "$1" "$2" | grep -oE '0x[0-9a-fA-F]{40}' | tail -1 || true; }

# cast call, printing the command
cc() { printf '  %s· cast call %s "%s" %s%s\n' "$DIM" "$1" "$2" "${*:3}" "$RESET"; cast call "$1" "$2" "${@:3}" --rpc-url "$RPC"; }

# cast send, confirm before sending; PRIV overridable for non-owner keys
cs() {
  local priv="${PRIV:-$PRIVATE_KEY}"
  printf '  %s將送出：%s cast send %s "%s" %s\n' "$YELLOW" "$RESET" "$1" "$2" "${*:3}"
  confirm "送出這筆交易？" || { warn "跳過"; return 1; }
  cast send "$1" "$2" "${@:3}" --private-key "$priv" --rpc-url "$RPC"
}

# patch one KEY: "0x…" line inside addresses.ts's BASE_SEPOLIA ChainAddresses block
patch_addr() {
  local key="$1" val="$2"
  awk -v k="$key" -v v="$val" '
    /^const BASE_SEPOLIA/ { inblk=1 }
    inblk && /^\}/        { inblk=0 }
    inblk && $0 ~ ("^[[:space:]]*" k ":[[:space:]]*\"0x") {
      sub(/"0x[0-9a-fA-F]+"/, "\"" v "\""); print; next
    }
    { print }
  ' "$ADDR_TS" > "$ADDR_TS.tmp" && mv "$ADDR_TS.tmp" "$ADDR_TS"
  ok "addresses.ts BASE_SEPOLIA.$key → $val"
}

# patch one KEY: "0x…" line inside V2_STACK[84532] (scoped to the V2_STACK Record).
# The Record ends with a bare `}` at column 0; its TYPE closes with `}> = {`,
# which we must NOT treat as the end — hence the `^\}$` anchor.
patch_v2stack() {
  local key="$1" val="$2"
  awk -v k="$key" -v v="$val" '
    /^export const V2_STACK/  { instack=1 }
    instack && /^\}$/         { instack=0 }
    instack && /^  84532: \{/ { inblk=1 }
    inblk && /^  \},/         { inblk=0 }
    inblk && $0 ~ ("^[[:space:]]*" k ":[[:space:]]*\"0x") {
      sub(/"0x[0-9a-fA-F]+"/, "\"" v "\""); print; next
    }
    { print }
  ' "$ADDR_TS" > "$ADDR_TS.tmp" && mv "$ADDR_TS.tmp" "$ADDR_TS"
  ok "addresses.ts V2_STACK[84532].$key → $val"
}

forge_run() {   # forge_run <ScriptFile:Contract> <logfile> [extra forge args...]
  local target="$1" logf="$2"; shift 2
  ( cd "$CONTRACTS" && forge script "script/$target" --rpc-url "$RPC" "$@" -vvv ) 2>&1 | tee "$logf"
  return "${PIPESTATUS[0]}"
}

