say "每筆帶 sourceHash = keccak256(來源網址 + 擷取日期)。"
if confirm "要布置多見證者（demo 用『三家機構意見不同』)？設 ATTESTOR_2 / ATTESTOR_3 兩把 EOA。"; then
  ask ATTESTOR_2 "ATTESTOR_2 地址（Enter 跳過）"; ask ATTESTOR_3 "ATTESTOR_3 地址（Enter 跳過）"
  [[ -n "${ATTESTOR_2:-}" ]] && export ATTESTOR_2
  [[ -n "${ATTESTOR_3:-}" ]] && export ATTESTOR_3
  warn "額外 attestor 必須各自用自己的 key 再跑一次 Deploy102CarbonRegistry（部署者這次先授它們 ATTESTOR_ROLE）。"
  warn "誠實揭露：那些 key 都是團隊持有 —— 畫面與文件都要這樣寫（#129 story 12）。"
fi
confirm "廣播 phase B？" || die "已中止"
LB="$REPO_ROOT/scripts/.log-129-b.txt"
forge_run "Deploy102CarbonRegistry.s.sol:Deploy102CarbonRegistry" "$LB" --private-key "$PRIVATE_KEY" --broadcast --slow $FORGE_VERIFY \
  || die "phase B 失敗 —— 看 $LB"
ESG_REGISTRY_V2="$(grab_addr 'ESGRegistryV2' "$LB")";           [[ -n "$ESG_REGISTRY_V2" ]] || die "撈不到 ESGRegistryV2 位址,看 $LB"
SUSTAINABILITY_BADGE="$(grab_addr 'SustainabilityBadge' "$LB")"; [[ -n "$SUSTAINABILITY_BADGE" ]] || die "撈不到 SustainabilityBadge 位址"
export ESG_REGISTRY_V2 SUSTAINABILITY_BADGE
remember ESG_REGISTRY_V2 "$ESG_REGISTRY_V2"
remember SUSTAINABILITY_BADGE "$SUSTAINABILITY_BADGE"
say "驗證見證（第一個回傳值是 tier：1=Low 2=Mid 3=High；最後一個 bool 要 true）："
for s in sMSFT sNVDA sGOLD sESGU; do
  cc "$ESG_REGISTRY_V2" 'medianCarbonTier(bytes32)(uint8,uint256,uint256,bool)' "$(cast keccak "$s")"
done
note "期望 sMSFT=3 · sNVDA=1 · sGOLD=3 · sESGU=2"
pause "Enter 繼續"
fi

# ── Stage 5 · 清空檢查（dry-run，不送鏈）────────────────────────────────
stage "清空檢查 —— 現行 exchange 還有幾個未平倉部位"
say "純讀取。Redeploy129Exchange 開頭會先驗 ESG_REGISTRY_V2 的 schema + seed —— 指錯或沒 seed 會在這裡 revert。"
LD="$REPO_ROOT/scripts/.log-129-dryrun.txt"
export DRY_RUN=true
forge_run "Redeploy129Exchange.s.sol:Redeploy129Exchange" "$LD" || { unset DRY_RUN; die "dry-run 失敗（多半是 ESG_REGISTRY_V2 不對）,看 $LD"; }
unset DRY_RUN
if grep -q "0 open positions on the old exchange" "$LD"; then
  ok "現行 exchange 0 未平倉 —— 可以切換"
else
  OPENCNT="$(grep -oiE 'open positions[[:space:]:]+[0-9]+' "$LD" | grep -oE '[0-9]+' | tail -1)"
  warn "現行 exchange 還有 ${OPENCNT:-一些} 個未平倉部位（上方 survey 有 id / owner）。"
  say  "每個 owner 自己平倉 + 提保證金,清到 0,再重跑本 wizard（會從 $SCRATCH 接續）："
  say  "  cast send $OLD_EXCHANGE 'closePosition(uint256)' <id>     --private-key <owner_key> --rpc-url \$BASE_SEPOLIA_RPC_URL"
  say  "  cast send $OLD_EXCHANGE 'withdrawMargin(uint256)' <amount> --private-key <owner_key> --rpc-url \$BASE_SEPOLIA_RPC_URL"
  warn "帶著未平倉切換 → phase C 第 5 步之後那些部位在舊 exchange 上 bailout 會 revert,平不掉也清算不了。"
  confirm "我了解風險,仍要帶著這 ${OPENCNT:-?} 個未平倉部位繼續" || die "先清空未平倉部位再重跑"
  warn "已選擇帶著未平倉部位繼續。"
fi
pause "Enter 進入不可逆的部署階段"

# ── Stage 6 · Phase C：碳定價連鎖重部署（不可逆點）─────────────────────
stage "Phase C — PerpetualExchange + StrategyRegistry + CopyTracker + AgentSessionManager + 重接線"
if [[ -n "${EXCHANGE_NEW:-}" ]]; then
  ok "已完成（EXCHANGE_NEW=$EXCHANGE_NEW）—— 跳過"; pause "Enter 繼續"
else
warn "最後兩個呼叫（InsuranceVault / FeeRouter.setExchange）之後,舊 exchange 上虧損部位就平不掉了。"
warn "確定現行 exchange 已清空、前面兩天緩衝還在。"
confirm "廣播 phase C？" || die "已中止（什麼都沒送）"
LC="$REPO_ROOT/scripts/.log-129-c.txt"
forge_run "Redeploy129Exchange.s.sol:Redeploy129Exchange" "$LC" --private-key "$PRIVATE_KEY" --broadcast --slow $FORGE_VERIFY \
  || die "phase C 跑到一半失敗 —— 看 $LC 與 contracts/broadcast/Redeploy129Exchange.s.sol/$CHAIN/run-latest.json。別重跑整段;用 cast 補完剩下的 onlyOwner setter。"
EXCHANGE_NEW="$(grab_addr 'PerpetualExchange_NEW' "$LC")"
STRATEGY_REGISTRY_NEW="$(grab_addr 'StrategyRegistry_NEW' "$LC")"
COPYTRACKER_NEW="$(grab_addr 'CopyTracker_NEW' "$LC")"
SESSION_MANAGER_NEW="$(grab_addr 'AgentSessionManager_NEW' "$LC")"
for v in EXCHANGE_NEW STRATEGY_REGISTRY_NEW COPYTRACKER_NEW SESSION_MANAGER_NEW; do
  [[ -n "${!v}" ]] || die "撈不到 $v,看 $LC"
done
export EXCHANGE_NEW STRATEGY_REGISTRY_NEW COPYTRACKER_NEW SESSION_MANAGER_NEW
remember EXCHANGE_NEW "$EXCHANGE_NEW"
remember STRATEGY_REGISTRY_NEW "$STRATEGY_REGISTRY_NEW"
remember COPYTRACKER_NEW "$COPYTRACKER_NEW"
remember SESSION_MANAGER_NEW "$SESSION_MANAGER_NEW"
ok "四合約已上鏈（腳本結尾的 require 全過 = 接線正確）"
pause "Enter 繼續"
fi

# ── Stage 7 · Phase D：獎勵發放 ─────────────────────────────────────────
stage "Phase D — EsgRewardDistributor（發 SustainabilityBadge,exchange 之後才能部署）"
if [[ -n "${REWARD_DISTRIBUTOR_NEW:-}" ]]; then
  ok "已完成（$REWARD_DISTRIBUTOR_NEW）—— 跳過"; pause "Enter 繼續"
else
confirm "部署 reward distributor？" || die "已中止"
export EXCHANGE_NEW ESG_REGISTRY_V2 SUSTAINABILITY_BADGE
LDD="$REPO_ROOT/scripts/.log-129-d.txt"
forge_run "Deploy102RewardDistributor.s.sol:Deploy102RewardDistributor" "$LDD" --private-key "$PRIVATE_KEY" --broadcast --slow $FORGE_VERIFY \
  || die "distributor 部署失敗,看 $LDD"
REWARD_DISTRIBUTOR_NEW="$(grab_addr 'EsgRewardDistributor' "$LDD")"; [[ -n "$REWARD_DISTRIBUTOR_NEW" ]] || die "撈不到 EsgRewardDistributor 位址"
export REWARD_DISTRIBUTOR_NEW
remember REWARD_DISTRIBUTOR_NEW "$REWARD_DISTRIBUTOR_NEW"
pause "Enter 繼續"
fi

# ── Stage 8 · Phase E：接金庫到登記所 + 開放鑄造 ──────────────────────
stage "Phase E — vault.setEsgRegistry + 設 cap + fundVault"
say "接上登記所後,金庫的鑄造費率才從『每檔 100』變成逐資產。"
export VAULT_PROXY_129 ESG_REGISTRY_V2
LE="$REPO_ROOT/scripts/.log-129-e.txt"
if [[ "$(cast call "$VAULT_PROXY_129" 'esgRegistry()(address)' --rpc-url "$RPC")" == "0x0000000000000000000000000000000000000000" ]]; then
  confirm "廣播 Wire129（setEsgRegistry）？" || die "已中止"
  forge_run "Wire129.s.sol:Wire129" "$LE" --private-key "$PRIVATE_KEY" --broadcast --slow \
    || die "Wire129 失敗 —— 多半是登記所沒 seed。看 $LE"
  ok "金庫已接登記所"
else
  ok "金庫已接登記所（esgRegistry != 0）—— 跳過 setEsgRegistry"
fi
cc "$VAULT_PROXY_129" 'mintFeeBpsForAsset(bytes32)(uint256)' "$(cast keccak sMSFT)";  note "期望 100（High）"
cc "$VAULT_PROXY_129" 'mintFeeBpsForAsset(bytes32)(uint256)' "$(cast keccak sNVDA)";  note "期望 10（Low）"
say ""
say "開放鑄造 —— 每檔設 cap（單位 token,18 位小數；金額跟風險組員確認）,然後 fundVault。"
say "cap 用 RISK_ROLE key（預設 = admin);fundVault 用 admin key。"
if confirm "現在逐檔設 cap？（會逐檔問金額,Enter 跳過該檔）"; then
  ask CAP_KEY "RISK_ROLE 的私鑰（Enter 用 PRIVATE_KEY）"
  for s in "${SYMS[@]}"; do
    ask CAPV "  $s 的 cap（token 數,例如 1000000,Enter 跳過）"
    if [[ -n "${CAPV:-}" ]]; then
      PRIV="${CAP_KEY:-$PRIVATE_KEY}" cs "$VAULT_PROXY_129" 'setAssetCap(bytes32,uint256)' "$(cast keccak "$s")" "$(cast to-wei "$CAPV" ether)" || true
    fi
    CAPV=""
  done
fi
ask FUND_USDC "fundVault 注入多少 USDC？（例如 100000,Enter 跳過）"
if [[ -n "${FUND_USDC:-}" ]]; then
  FW="$(cast to-wei "$FUND_USDC" ether)"
  warn "先 approve：cast send $USDC 'approve(address,uint256)' $VAULT_PROXY_129 $FW --private-key <admin>"
  cs "$USDC" 'approve(address,uint256)' "$VAULT_PROXY_129" "$FW" || true
  cs "$VAULT_PROXY_129" 'fundVault(uint256)' "$FW" || true
fi
pause "Enter 繼續"

# ── Stage 9 · Phase F：逐項驗證 ────────────────────────────────────────
stage "Phase F — Verify129（唯讀,整張相依圖）"
say "第一個不符就 revert 並印欄位名。"
export GUARDED_ORACLE_129 VAULT_PROXY_129 ESG_REGISTRY_V2 SUSTAINABILITY_BADGE \
       EXCHANGE_NEW COPYTRACKER_NEW STRATEGY_REGISTRY_NEW SESSION_MANAGER_NEW REWARD_DISTRIBUTOR_NEW
LF="$REPO_ROOT/scripts/.log-129-f.txt"
forge_run "Verify129.s.sol:Verify129" "$LF" \
  && ok "Verify129 全綠 —— 合約接線完成（畫面驗收仍要人工走 §11）" \
  || die "Verify129 失敗 —— 看 $LF 最後幾行的 MISMATCH 欄位,對照 docs/DEPLOY_129_CUTOVER.md §12"
pause "Enter 繼續"

# ── Stage 10 · 回填 addresses.ts + ABI ────────────────────────────────
stage "回填 frontend/src/contracts/addresses.ts + 複製 ABI"
warn "一次改完 —— ChainAddresses 的 exchange 欄位沒有 hasV2Stack 那種 0x0 退回閘,分批改會裂腦。"
say "V2_STACK[84532]："
patch_v2stack GuardedOracle       "$GUARDED_ORACLE_129"
patch_v2stack AssetVaultV2        "$VAULT_PROXY_129"
patch_v2stack ESGRegistryV2       "$ESG_REGISTRY_V2"
patch_v2stack SustainabilityBadge "$SUSTAINABILITY_BADGE"
say "BASE_SEPOLIA ChainAddresses："
patch_addr PerpetualExchange    "$EXCHANGE_NEW"
patch_addr StrategyRegistry     "$STRATEGY_REGISTRY_NEW"
patch_addr CopyTracker          "$COPYTRACKER_NEW"
patch_addr ESGRegistry          "$ESG_REGISTRY_V2"
patch_addr EsgRewardDistributor "$REWARD_DISTRIBUTOR_NEW"
say ""
warn "V2_STACK[84532].tokens 的 11 顆要手動貼（scripts/.tokens-129.txt）。貼成這個形狀,取代空的 tokens: {}："
if [[ -f "$REPO_ROOT/scripts/.tokens-129.txt" ]]; then
  printf '    tokens: {\n'
  while read -r s a; do printf '      %-7s "%s",\n' "$s:" "$a"; done < "$REPO_ROOT/scripts/.tokens-129.txt"
  printf '    },\n'
fi
say ""
say "複製新 ABI（只取 .abi 陣列）："
for n in PerpetualExchange CopyTracker StrategyRegistry AgentSessionManager AssetVaultV2_4 ESGRegistryV2 GuardedOracle SustainabilityBadge EsgRewardDistributor; do
  src="$CONTRACTS/out/$n.sol/$n.json"
  # AssetVaultV2_4 → 前端沿用 AssetVaultV2.json 檔名
  dstname="$n"; [[ "$n" == "AssetVaultV2_4" ]] && dstname="AssetVaultV2"
  dst="$REPO_ROOT/frontend/src/contracts/abi/$dstname.json"
  [[ -f "$src" ]] || { warn "找不到 $src"; continue; }
  jq '.abi' "$src" > "$dst" && ok "abi/$dstname.json"
done
say ""
say "git diff 檢查 addresses.ts,把 tokens 貼進去,開 PR。"
pause "貼完 tokens、確認 diff 後 Enter"

# ── Stage 11 · agent/.env + 重建 ──────────────────────────────────────
stage "agent/.env + 重建前端 / agent"
say "在 agent/.env 設（wizard 不自動改 —— 那檔有其他內容）："
say  "  SESSION_MANAGER_ADDRESS=$SESSION_MANAGER_NEW"
say  "  DEMO_SESSION_ID=0"
say  "  PERP_ADDRESS=$EXCHANGE_NEW"
say  "  KEEPER_GUARDED_ORACLE=$GUARDED_ORACLE_129"
say  "  KEEPER_VAULT_ADDRESS=$VAULT_PROXY_129"
pause "改完 agent/.env 後 Enter"
if confirm "現在跑 frontend 的 tsc + vitest？"; then
  run bash -c "cd '$REPO_ROOT/frontend' && yarn install --frozen-lockfile && yarn tsc --noEmit && yarn vitest run" || warn "前端有問題 —— 修完再部署站台"
fi
if confirm "跑 agent 的 typecheck + test？"; then
  run bash -c "cd '$REPO_ROOT/agent' && npm install && npm run typecheck && npm test" || warn "agent 有問題"
fi
say "記得：部署前端站台;重啟 signal-api / keeper / mcp-server（從 addresses.ts 讀新位址）。"
say "keeper 第一輪會為 11 檔寫新價（MockOracle + GuardedOracle）—— 盯 sBOND 有沒有 DeviationTooLarge。"
say "確認 keeper 至少跑過一輪 observeReserve()（KEEPER_VAULT_ADDRESS 已設）→ 新金庫的 ReserveObserved 事件上鏈。"
pause "Enter 進入收尾"

# ── Stage 12 · demo 策略 + 收尾 ───────────────────────────────────────
stage "demo 策略 + 收尾"
say "新 StrategyRegistry 是空的。至少 3 份 Allocation（每份 ≥3 資產、每權重 ≤5000bps、加總 10000、全 1x）。"
if confirm "用部署者帳號 registerTrader + 發 3 份（低碳保守 / 均衡 / 成長)？"; then
  cs "$STRATEGY_REGISTRY_NEW" 'registerTrader(string)' "PepeLab Demo" || true
  KA(){ cast keccak "$1"; }
  cs "$STRATEGY_REGISTRY_NEW" 'publishStrategy((bytes32,uint256,bool,uint256)[])' \
    "[($(KA sICLN),3400,true,1),($(KA sBOND),3300,true,1),($(KA sNVDA),3300,true,1)]" || warn "低碳保守 失敗"
  cs "$STRATEGY_REGISTRY_NEW" 'publishStrategy((bytes32,uint256,bool,uint256)[])' \
    "[($(KA sAAPL),2500,true,1),($(KA sESGU),2500,true,1),($(KA sGOLD),2500,true,1),($(KA sETH),2500,true,1)]" || warn "均衡 失敗"
  cs "$STRATEGY_REGISTRY_NEW" 'publishStrategy((bytes32,uint256,bool,uint256)[])' \
    "[($(KA sNVDA),4000,true,1),($(KA sMSFT),3000,true,1),($(KA sGOOGL),3000,true,1)]" || warn "成長 失敗"
  ok "策略發布嘗試完成 —— /marketplace 確認看得到 3 份"
else
  warn "跳過 —— demo 前一定要有至少 3 份"
fi
say ""
say "所有新位址（也存在 $SCRATCH）："; cat "$SCRATCH"
say ""
say "還沒自動化、要你自己做的（docs/DEPLOY_129_CUTOVER.md §11 六條畫面驗收）："
step "資產頁讀得到儲備率;預言機失效時顯示「無法確認」"
step "11 檔各自顯示得出被見證的分級與筆數"
step "低碳 vs 高碳買入費率確實不同（sNVDA 0.10% / sMSFT 1.00%）"
step "試調單一資產買入費率 → 失敗;試為特定使用者豁免碳費率 → 失敗（先排練打哪個呼叫）"
step "走過 11 頁 Expert Mode"
step "把新位址 + 發布帳號更新到 issue #129"
open_url "https://github.com/zuemen/pepelab_onchain_cfd/issues/129"

finish
